#include <DHT.h>
#include <EEPROM.h>

#define DHT_PIN 2  // Pin connected to DHT22 sensor
#define EEPROM_ADDRESS 0  // Address in EEPROM to store calibration data

DHT dht(DHT_PIN, DHT22);

// Calibration data structure
struct CalibrationData {
  float temperatureCoeff[256];  // 256 possible humidity values
  float humidityCoeff[256];  // 256 possible temperature values
};

CalibrationData calibrationData;

void setup() {
  Serial.begin(9600);
  dht.begin();

  // Read stored calibration data from EEPROM
  if (EEPROM.read(EEPROM_ADDRESS) == 0) {
    // Perform calibration if no data is stored
    performCalibration();
  } else {
    // Load stored calibration data
    for (int i = 0; i < 256; i++) {
      calibrationData.temperatureCoeff[i] = EEPROM.read(i * 2 + EEPROM_ADDRESS);
      calibrationData.humidityCoeff[i] = EEPROM.read(i * 2 + EEPROM_ADDRESS + 1);
    }
  }
}

void loop() {
  // Read temperature and humidity data from DHT22 sensor
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  // Apply calibration coefficients
  for (int i = 0; i < 256; i++) {
    if (abs(humidity - i * (100.0 / 255.0)) < 0.1) {  // Find matching humidity value
      for (int j = 0; j < 256; j++) {
        if (abs(temperature - j * (50.0 / 255.0)) < 0.1) {  // Find matching temperature value
          humidity = calibrationData.temperatureCoeff[i] + (humidity - i * (100.0 / 255.0)) * calibrationData.humidityCoeff[j];
          temperature = j * (50.0 / 255.0);
          break;
        }
      }
      break;
    }
  }

  // Print calibrated temperature and humidity values
  Serial.print("Temperature: ");
  Serial.print(temperature);
  Serial.println(",");
  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.println("%");
}

void performCalibration() {
  float temperatures[256];
  float humidities[256];

  // Take readings for all possible humidity and temperature values
  for (int i = 0; i < 256; i++) {
    for (int j = 0; j < 256; j++) {
      dht.read Humidity();
      dht.readTemperature();
      humidities[i] = j * (100.0 / 255.0);
      temperatures[j] = i * (50.0 / 255.0);
    }
  }

