location ~ /posts/(.*)\.html {
  root /usr/share/nginx/html;
  alias /usr/share/nginx/html/posts/$1;
  try_files $uri $uri/ =404;
  echo "Generating link for post: $uri";
  echo "<a href=\"$uri\">Read more...</a>" > /usr/share/nginx/html/posts/$1/_link.html;
  index _link.html;
}
```
